import carb
import ssl
from urllib.parse import urlsplit
from urllib import request


def is_http_url_accessible(url: str, timeout: float = 3.0):
    """
    Return (reachable: bool, status_code: int|None).

    'reachable' means we connected and got an HTTP response at all.
    Redirects (3xx) are NOT followed but counted as reachable.
    For HTTPS, the default SSL context is used (certificate verification enabled).
    If HTTPS fails due to certificate verification (e.g. self-signed or expired cert),
    the function returns (False, None) and a clear message is logged; no exception
    is raised. Callers only need to check the return value.
    """
    u = urlsplit(url)
    if u.scheme not in ("http", "https"):
        return (False, None)

    host = u.hostname
    if not host:
        return (False, None)

    try:
        carb.log_info(f"Checking HTTP reachability for {url} (timeout={timeout})")
        if u.scheme == "https":
            ctx = ssl.create_default_context()
        else:
            ctx = None

        req = request.Request(url, method="HEAD")

        # Disable any special handling for non-200 error codes. Won't raise HTTPError and won't
        # handle redirects (HTTPRedirectHandler) but simply report them as status 30x.
        class DisableHTTPErrorProcessor(request.HTTPErrorProcessor):
            def http_response(self, request, response):
                return response

            https_response = http_response

        opener = request.build_opener(
            DisableHTTPErrorProcessor,
            request.HTTPSHandler(context=ctx),
        )

        with opener.open(req, timeout=timeout) as f:
            # Any response means it's reachable (2xx, 3xx, 4xx, 5xx, etc.)
            return (True, f.status)
    except ssl.SSLCertVerificationError as e:
        carb.log_info(
            f"HTTP reachability check failed for {url}: SSL certificate verification failed "
            f"(e.g. self-signed, expired, or wrong host). Details: {e}"
        )
        return (False, None)
    except Exception as e:
        carb.log_info(f"HTTP reachability check failed for {url} ({type(e).__name__}: {e})")
        return (False, None)
